helper:{zh:"用于输入框翻译。",en:"Used for input box translation.",zh_TW:"用於輸入框翻譯。",ja:"入力ボックスの翻訳に使用します。",ko:"입력창 번역에 사용됩니다."},trigger_trans_shortcut:{zh:"触发翻译快捷键",en:"Trigger Translation Shortcut Keys",zh_TW:"觸發翻譯快速鍵",ja:"翻訳ショートカットキー",ko:"번역 실행 단축키"},trigger_trans_shortcut_help:{zh:"默认为单击“AltLeft+KeyI”",en:'Default is "AltLeft+KeyI"',zh_TW:"預設為按下「AltLeft+KeyI」",ja:"デフォルトは「AltLeft+KeyI」です",ko:'기본값 "AltLeft+KeyI"'},shortcut_press_count:{zh:"快捷键连击次数",en:"Shortcut Press Number",zh_TW:"快速鍵連按次數",ja:"ショートカットの連続プレス回数",ko:"단축키 연속 입력 횟수"},combo_timeout:{zh:"连击超时时间 (10-1000ms)",en:"Combo Timeout (10-1000ms)",zh_TW:"連擊逾時 (10-1000ms)",ja:"連続プレスタイムアウト (10-1000ms)",ko:"연속 입력 시간 초과 (10-1000ms)"},input_trans_start_sign:{zh:"翻译起始标识",en:"Translation Start Sign",zh_TW:"翻譯起始標記",ja:"翻訳開始記号",ko:"번역 시작 표시"},input_trans_start_sign_help:{zh:"标识后面可以加目标语言代码，如： “/en 你好”、“/zh hello”",en:'The target language code can be added after the sign, such as: "/en 你好", "/zh hello"',zh_TW:"標記後可加上目標語言代碼，例如：「/en 你好」、「/zh hello」",ja:"記号の後に対象言語コードを追加できます。例：「/en 你好」、「/zh hello」",ko:'표시 뒤에 대상 언어 코드를 추가할 수 있습니다. 예: "/en 你好", "/zh hello"'},detect_lang_remote:{zh:"远程语言检测",en:"Remote language detection",zh_TW:"遠端語言偵測",ja:"リモート言語検出",ko:"원격 언어 감지"},detect_lang_remote_help:{zh:"启用后检测准确度增加，但会降低翻译速度，请酌情开启",en:"After enabling, the detection accuracy will increase, but it will reduce the translation speed. Please enable it as appropriate.",zh_TW:"啟用後可提升偵測準確度，但會降低翻譯速度，請視需要開啟。",ja:"有効にすると検出精度が向上しますが、翻訳速度が低下する可能性があります。必要に応じて有効にしてください。",ko:"활성화하면 감지 정확도가 높아지지만 번역 속도가 느려질 수 있습니다. 적절히 활성화하십시오."},detect_lang_service:{zh:"语言检测服务",en:"Language detect service",zh_TW:"語言偵測服務",ja:"言語検出サービス",ko:"언어 감지 서비스"},disable:{zh:"禁用",en:"Disable",zh_TW:"停用",ja:"無効",ko:"비활성화"},enable:{zh:"启用",en:"Enable",zh_TW:"啟用",ja:"有効",ko:"활성화"},selection_translate:{zh:"划词翻译",en:"Selection Translation",zh_TW:"選取文字翻譯",ja:"選択翻訳",ko:"선택 번역"},toggle_selection_translate:{zh:"启用划词翻译",en:"Use Selection Translate",zh_TW:"啟用選取文字翻譯",ja:"選択翻訳を有効にする",ko:"선택 번역 사용"},trigger_tran